from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    # framework lines: line whose dominant color is not bg
    frows=[i for i in range(H) if Counter(g[i]).most_common(1)[0][0]!=bg]
    fcols=[j for j in range(W) if Counter([g[i][j] for i in range(H)]).most_common(1)[0][0]!=bg]
    # rare colors: colors at intersections of framework lines that aren't the framework line color
    inter={}
    for i in frows:
        for j in fcols:
            inter[(i,j)]=g[i][j]
    # rare = intersection colors != the line color (line color = dominant of its line)
    def linecol_row(i): return Counter(g[i]).most_common(1)[0][0]
    def linecol_col(j): return Counter([g[i][j] for i in range(H)]).most_common(1)[0][0]
    rarecolors={v for (i,j),v in inter.items() if v!=linecol_row(i) and v!=linecol_col(j)}
    out=[]
    for a in range(len(frows)-1):
        r0,r1=frows[a],frows[a+1]
        row=[]
        any_rect=False
        for b in range(len(fcols)-1):
            c0,c1=fcols[b],fcols[b+1]
            cs=[g[r0][c0],g[r0][c1],g[r1][c0],g[r1][c1]]
            if cs[0]==cs[1]==cs[2]==cs[3] and cs[0] in rarecolors:
                row.append(cs[0]); any_rect=True
            else:
                row.append(bg)
        if any_rect: out.append(row)
    return out

